import type { Finding } from "./types.js";

/**
 * Content Credentials (C2PA): a signed label inside an image file that says how it was made,
 * for example "generated by an AI model" or "captured by a camera", and who signed that
 * statement. Unlike AI detectors, this is a statement someone signed, not a guess. Most images
 * on the web carry no label (sites often strip it), and then Satya says nothing about them.
 *
 * This file turns a manifest store (as returned by the C2PA SDK) into plain findings.
 */

/** The parts of a C2PA manifest store Satya reads. Field names follow c2pa-rs's JSON. */
export interface ManifestStoreLike {
  active_manifest?: string | null;
  manifests?: Record<string, ManifestLike>;
  validation_state?: string | null;
  validation_status?: { code: string; explanation?: string | null }[] | null;
}
interface ManifestLike {
  claim_generator?: string | null;
  claim_generator_info?: { name?: string; version?: string }[] | null;
  assertions?: { label: string; data?: unknown }[] | null;
  signature_info?: { issuer?: string | null; common_name?: string | null; time?: string | null } | null;
}

export type ImageOrigin = "ai" | "ai-edited" | "camera" | "computer" | "unknown";

export interface ImageCredential {
  url: string;
  origin: ImageOrigin;
  /** Who signed the label (certificate issuer / name), if readable. */
  signer?: string;
  /** The app that wrote the label, e.g. "Adobe Firefly" or "ChatGPT". */
  generator?: string;
  /** True when the label doesn't match the image or its signature fails. */
  broken: boolean;
  /** Validation codes that explain a broken label. */
  problems: string[];
  /** The signer isn't on the C2PA trust list this check knows (e.g. a test certificate). */
  untrustedSigner: boolean;
}

// IPTC digital source types. "trainedAlgorithmicMedia" is generative AI; plain
// "algorithmicMedia" is made by an algorithm without training data (e.g. a drawn gradient).
const AI = /\/trainedAlgorithmicMedia$/;
const COMPUTER = /\/algorithmicMedia$/;
const AI_EDITED = /\/compositeWithTrainedAlgorithmicMedia$/;
const CAMERA = /\/(digitalCapture|computationalCapture)$/;

/** Validation codes that mean the label is not trustworthy for this image. */
const BROKEN_CODES = /mismatch|invalid|missing|\.malformed|revoked|expired/i;

function sourceTypes(m: ManifestLike): string[] {
  const out: string[] = [];
  for (const a of m.assertions ?? []) {
    if (!a.label.startsWith("c2pa.actions")) continue;
    const actions = (a.data as { actions?: { digitalSourceType?: string }[] } | undefined)?.actions ?? [];
    for (const act of actions) if (act.digitalSourceType) out.push(act.digitalSourceType);
  }
  return out;
}

/** Summarises one image's manifest store. Returns undefined when the image has no label. */
export function readCredential(url: string, store: ManifestStoreLike | null | undefined): ImageCredential | undefined {
  const label = store?.active_manifest;
  const m = label ? store?.manifests?.[label] : undefined;
  if (!store || !m) return undefined;
  const types = sourceTypes(m);
  const origin: ImageOrigin = types.some((t) => AI.test(t))
    ? "ai"
    : types.some((t) => AI_EDITED.test(t))
      ? "ai-edited"
      : types.some((t) => CAMERA.test(t))
        ? "camera"
        : types.some((t) => COMPUTER.test(t))
          ? "computer"
          : "unknown";
  const problems = (store.validation_status ?? []).map((s) => s.code).filter((c) => BROKEN_CODES.test(c));
  const generator = m.claim_generator_info?.[0]?.name ?? m.claim_generator?.split(/[ /]/)[0] ?? undefined;
  const signer = m.signature_info?.issuer ?? m.signature_info?.common_name ?? undefined;
  return {
    url,
    origin,
    signer: signer || undefined,
    generator: generator || undefined,
    broken: problems.length > 0 || store.validation_state === "Invalid",
    problems,
    untrustedSigner: (store.validation_status ?? []).some((s) => s.code === "signingCredential.untrusted"),
  };
}

const fileName = (url: string) => {
  try {
    return decodeURIComponent(new URL(url).pathname.split("/").pop() || url);
  } catch {
    return url;
  }
};

/** Findings for the images that carry Content Credentials. */
export function credentialFindings(creds: ImageCredential[], imagesChecked: number): Finding[] {
  const findings: Finding[] = [];
  const source = "Content Credentials (C2PA) in the image file";
  for (const c of creds) {
    const who = [c.generator && `made with ${c.generator}`, c.signer && `signed by ${c.signer}`].filter(Boolean).join(", ");
    const name = fileName(c.url);
    const trust = c.untrustedSigner ? " The signer isn't on the official C2PA trust list, so treat who signed it with care." : "";
    if (c.broken) {
      findings.push({
        check: "ai",
        severity: "warning",
        title: `Image "${name}" has a broken Content Credentials label`,
        detail: `The signed label doesn't match this image or its signature fails (${c.problems.slice(0, 2).join(", ") || "invalid"}), so the image may have been altered after it was labelled.`,
        source,
        weight: 10,
      });
    } else if (c.origin === "ai") {
      findings.push({
        check: "ai",
        severity: "info",
        title: `Image "${name}" was made by AI`,
        detail: `Its signed label says it was generated by an AI model${who ? ` (${who})` : ""}. It isn't a real photo.${trust}`,
        source,
        weight: 0,
      });
    } else if (c.origin === "ai-edited") {
      findings.push({
        check: "ai",
        severity: "info",
        title: `Image "${name}" was edited with AI`,
        detail: `Its signed label says AI was used to change it${who ? ` (${who})` : ""}.${trust}`,
        source,
        weight: 0,
      });
    } else if (c.origin === "camera") {
      findings.push({
        check: "ai",
        severity: "good",
        title: `Image "${name}" is a camera photo`,
        detail: `Its signed label says it was captured by a camera${who ? ` (${who})` : ""}.${trust}`,
        source,
        weight: 0,
      });
    } else if (c.origin === "computer") {
      findings.push({
        check: "ai",
        severity: "info",
        title: `Image "${name}" was drawn by a computer program, not AI`,
        detail: `Its signed label says software made it without AI${who ? ` (${who})` : ""}.${trust}`,
        source,
        weight: 0,
      });
    } else {
      findings.push({
        check: "ai",
        severity: "info",
        title: `Image "${name}" has Content Credentials`,
        detail: `It carries a valid signed label${who ? ` (${who})` : ""}, but the label doesn't say whether AI made it.${trust}`,
        source,
        weight: 0,
      });
    }
  }
  if (imagesChecked > 0) {
    findings.push({
      check: "ai",
      severity: "info",
      title: `Checked ${imagesChecked} image${imagesChecked > 1 ? "s" : ""} for Content Credentials: ${creds.length} had them`,
      detail: "Most images on the web carry no label, and that alone doesn't mean anything.",
      source,
      weight: 0,
    });
  }
  return findings;
}
